# frozen_string_literal: true

require_relative 'model'

module Schema
  module Generate
    # Writes the Ruby of the generated values: a Data class per message, a module per enum. Every other type is
    # named from +::+: a package such as +ajax.dcp.v1+ gives a +Messages::Ajax+ that would hide +::Ajax+.
    module Ruby
      HEADER = "# frozen_string_literal: true\n\n# Generated by schema/generate.rb from lib/ajax/sdk/cloud/schemas/; " \
               "do not edit.\n"
      CLOUD = '::Ajax::Sdk::Cloud'
      YARD = { double: 'Float', float: 'Float', bool: 'Boolean', string: 'String', bytes: 'String' }.freeze

      module_function

      # @return [String] the Ruby of the types +proto+ declares
      def file(model, proto)
        types = model.top_level(proto)
        body = types.map { type(model, it) }.reduce { |all, lines| [*all, '', *lines] }
        [HEADER, "module #{types.first.constant.rpartition('::').first}", *indent(body), 'end', ''].join("\n")
      end

      def type(model, type) = type.is_a?(Message) ? message(model, type) : enum(type)

      def indent(lines) = lines.map { it.empty? ? it : "  #{it}" }

      def short(type) = type.constant.split('::').last

      def message(model, message)
        members = [*message.fields.map(&:name), :raw].map(&:inspect).join(', ')
        [*doc(model, message), "#{short(message)} = ::Data.define(#{members})", '', "class #{short(message)}",
         *indent(body(model, message)), 'end']
      end

      def doc(model, message)
        attributes = message.fields.flat_map do |field|
          ["# @!attribute [r] #{field.name}",
           "#   @return [#{yard(model, field)}] field #{field.number}, +#{proto(field)}+"]
        end
        ["# +#{message.full_name}+, from +#{message.file}+.", '#', *attributes, '# @!attribute [r] raw',
         "#   @return [Hash{Symbol=>Object}] the message as google-protobuf's +to_h+ gave it"]
      end

      def body(model, message)
        [*constants(model, message), '', *from(model, message), '',
         'def initialize(**fields) = super(**DEFAULTS, **fields)', '', *to_message(model, message),
         *message.oneofs.flat_map { ['', *oneof(it)] }, *outcome(message),
         *model.nested(message.full_name).flat_map { ['', *type(model, it)] }]
      end

      def constants(model, message)
        defaults = message.fields.map { "#{it.name.inspect} => #{Expressions.default(model, it)}" }
        defaults << ':raw => {}.freeze'
        oneofs = message.oneofs.map { "#{it.reader.inspect} => %i[#{it.choices.join(' ')}]" }
        ["DEFAULTS = { #{defaults.join(', ')} }.freeze", 'private_constant :DEFAULTS', '',
         '# The members of each oneof, by the name of its reader.',
         "ONEOFS = #{oneofs.empty? ? '{}' : "{ #{oneofs.join(', ')} }"}.freeze"]
      end

      def from(model, message)
        reads = [*message.fields.map { "#{it.name.inspect} => #{Expressions.read(model, it)}," }, ':raw => hash']
        ["# @param hash [Hash{Symbol=>Object}] the message as google-protobuf's +to_h+ gives it",
         "# @return [#{short(message)}]", 'def self.from(hash)', '  new(', *reads.map { "    #{it}" }, '  )', 'end']
      end

      def to_message(model, message)
        doc = '# @return [Hash{Symbol=>Object}] the message as google-protobuf takes it'
        return [doc, 'def to_message = {}'] if message.fields.empty?

        writes = message.fields.map { "#{it.key.inspect} => #{Expressions.write(model, it, "self.#{it.name}")}," }
        [doc, 'def to_message', '  {', *writes.map { "    #{it}" }, '  }.compact', 'end']
      end

      def oneof(oneof)
        choices = oneof.choices.map { "+#{it.inspect}+" }.join(', ')
        ["# @return [Symbol, nil] the member of the oneof +#{oneof.name}+ that is set: #{choices}",
         "def #{oneof.reader} = ONEOFS.fetch(#{oneof.reader.inspect}).find { !public_send(it).nil? }"]
      end

      def outcome(message)
        return [] unless message.outcome

        ['', "include #{CLOUD}::Outcome", '', "# @return [Object, nil] the +#{message.outcome}+ member, when it is set",
         "def problem = #{message.outcome}"]
      end

      def proto(field) = field.map ? "map<#{field.map.first.type}, #{field.map.last.type}>" : field.type.to_s

      def yard(model, field)
        return "Hash{#{yard_type(model, field.map.first)}=>#{yard_type(model, field.map.last)}}" if field.map
        return "Array<#{yard_type(model, field)}>" if field.list?

        "#{yard_type(model, field)}#{', nil' if field.nilable?}"
      end

      def yard_type(model, field)
        case field.kind
        when :enum then 'Symbol, Integer'
        when :message then model.constant(field.type)
        when :timestamp then 'Time'
        when :duration then 'Float'
        when :wrapper then YARD.fetch(Shapes::WRAPPERS.fetch(field.type), 'Integer')
        else YARD.fetch(field.type, 'Integer')
        end
      end

      def enum(enum)
        values = enum.values.map { |name, symbol| "#{name}: #{symbol.inspect}" }.join(', ')
        ["# +#{enum.full_name}+, from +#{enum.file}+.", "module #{short(enum)}", "  extend #{CLOUD}::Enum", '',
         '  # The short symbol of each protobuf value, the default first.', "  VALUES = { #{values} }.freeze", 'end']
      end
    end

    # The Ruby expressions that read a field from +to_h+, write it back for google-protobuf, and give its default.
    module Expressions
      CLOUD = Ruby::CLOUD
      DEFAULTS = { double: '0.0', float: '0.0', bool: 'false', string: "''", bytes: "''" }.freeze

      module_function

      def default(model, field)
        return '{}.freeze' if field.map
        return '[].freeze' if field.list?
        return 'nil' if field.nilable?
        return model.type(field.type).values.first.last.inspect if field.kind == :enum

        DEFAULTS.fetch(field.type, '0')
      end

      def read(model, field)
        key = field.key.inspect
        return "hash.fetch(#{key}, {})#{each(:transform_values, convert(model, field.map.last, 'it'))}" if field.map
        return "hash.fetch(#{key}, [])#{each(:map, convert(model, field, 'it'))}" if field.list?

        read_one(model, field, key)
      end

      def read_one(model, field, key)
        return "hash.fetch(#{key}, #{default(model, field)})" unless field.nilable? || field.kind == :enum
        return convert(model, field, "hash[#{key}]") if %i[timestamp duration wrapper].include?(field.kind)
        return convert(model, field, "hash[#{key}]") unless field.nilable?

        "hash[#{key}]#{each(:then, convert(model, field, 'it'), '&.')}"
      end

      def each(method, conversion, call = '.') = conversion == 'it' ? '' : "#{call}#{method} { #{conversion} }"

      def convert(model, field, value)
        case field.kind
        when :enum, :message then "::#{model.constant(field.type)}.from(#{value})"
        when :timestamp then "#{CLOUD}::Decode.time(#{value})"
        when :duration then "#{CLOUD}::Decode.duration(#{value})"
        when :wrapper then "#{CLOUD}::Decode.wrapper(#{value}, #{wrapped_default(field)})"
        else value
        end
      end

      def wrapped_default(field) = DEFAULTS.fetch(Shapes::WRAPPERS.fetch(field.type), '0')

      def write(model, field, value)
        return "#{value}#{each(:transform_values, back(model, field.map.last, 'it'))}" if field.map
        return "#{value}#{each(:map, back(model, field, 'it'))}" if field.list?

        "#{value}#{each(:then, back(model, field, 'it'), '&.')}"
      end

      def back(model, field, value)
        case field.kind
        when :enum then "::#{model.constant(field.type)}.proto(#{value})"
        when :message then "#{CLOUD}::Encode.message(#{value}, ::#{model.constant(field.type)})"
        when :timestamp then "#{CLOUD}::Encode.time(#{value})"
        when :duration then "#{CLOUD}::Encode.duration(#{value})"
        when :wrapper then "#{CLOUD}::Encode.wrapper(#{value})"
        else value
        end
      end
    end
  end
end
